from pathlib import Path
import json,re
B=Path(__file__).resolve().parent.parent; R=B/'revisao-r54'
base=json.loads((B/'revisao-r53/BLOCOS-R53.json').read_text());d=dict(base);ops=[]
def rep(k,a,z,reason):
 assert d[k].count(a)==1,(k,a[:110],d[k].count(a))
 d[k]=d[k].replace(a,z,1);ops.append(dict(bloco=k,antes=a,depois=z,motivo=reason,passada=1))
def after(k,a,z,reason):rep(k,a,a+'\n\n'+z,reason)
def before(k,a,z,reason):rep(k,a,z+'\n\n'+a,reason)
rep('ab--ab-primeira-sessao','O mestre informa o nível e os recursos iniciais. O padrão deste livro é **nível 2**, com personagens que já escolheram sua primeira Trilha. Uma campanha pode começar no nível 1, antes dessas habilidades. A patente inicial padrão é Grau 4. Nível e patente têm funções diferentes, explicadas em Progressão.',
'O mestre informa o **nível**, que determina os avanços do personagem, e os recursos iniciais. O padrão deste livro é **nível 2**. Nesse nível, você já escolheu um **Caminho**, que reúne suas habilidades de atuação, e uma **Trilha**, a especialização dentro dele. Uma campanha pode começar no nível 1, antes dessas habilidades.\n\nA **patente** representa seu reconhecimento no meio jujutsu. A patente inicial padrão é **Grau 4**. Consulte [Progressão](#progressao--prog-inicio) para os avanços de nível e de patente.', 'Apresentar nível, Caminho, Trilha e patente antes de pedir essas escolhas.')
rep('ab--ab-mundo','No jogo, você descreve sua técnica e monta suas aplicações usando o Fundamento. Chamamos cada aplicação preparada de **feitiço**. Pontos de energia, Classes, espaços conhecidos e demais valores são regras do Ciclo Maldito para organizar seu uso na mesa.',
'No jogo, o **Fundamento** registra o funcionamento e os limites da sua técnica. Cada aplicação preparada se chama **feitiço** e tem uma ficha com seus efeitos e custos. Os **Pontos de Energia (PE)** são a reserva que você gasta para usar capacidades que cobram energia.\n\nA **Classe** é o patamar de montagem e conjuração de um feitiço: define seus pontos, custo e limites. Seu nível determina a maior Classe disponível. Os **espaços conhecidos** são as vagas do repertório onde você registra as aplicações aprendidas; usar uma delas conserva a vaga ocupada e gasta os recursos indicados na ficha. A criação é explicada em [Fundamento](#fundamento--fundamento).', 'Introduzir os recursos e as escalas usados nos capítulos anteriores ao Fundamento.')
a='Os cinco atributos variam de **0 a 6**. O valor anotado já é o modificador: Força 3 acrescenta 3 a uma rolagem que use Força.'
